create table t(a int, b text, c real);
insert into t values(1,'x',1.5),(2,'y',2.5),(3,'x',3.5),(4,'y',4.5),(5,'x',5.5),(6,'z',null),(7,'x',7),(8,'y',8),(9,'z',9),(10,'x',10);
select a, row_number() over (order by a) from t;
select a, b, rank() over (partition by b order by a), dense_rank() over (order by b) from t order by a;
select a, sum(a) over (order by a rows between 1 preceding and 1 following) from t;
select a, sum(c) over (partition by b order by a rows unbounded preceding) from t order by a;
select a, avg(a) over (order by a range between 2 preceding and current row) from t;
select a, count(*) over (order by c range between 1.0 preceding and 1.0 following) from t order by a;
select a, min(a) over (order by a rows between 2 preceding and 2 following), max(a) over (order by a rows between 3 preceding and current row) from t;
select a, first_value(b) over w, last_value(b) over w, nth_value(b, 2) over w from t window w as (order by a rows between 1 preceding and 2 following);
select a, lead(a) over (order by a), lag(a, 2) over (order by a), lead(b, 1, 'none') over (order by a) from t;
select a, ntile(3) over (order by a), percent_rank() over (order by a), cume_dist() over (order by b) from t;
select a, group_concat(b, '.') over (order by a groups between 1 preceding and 1 following) from t;
select a, sum(a) over (order by a rows between unbounded preceding and unbounded following exclude current row) from t;
select a, sum(a) over (order by b groups between current row and unbounded following exclude ties) from t order by a;
select a, sum(a) over (order by b range between unbounded preceding and current row exclude group) from t order by a;
select b, sum(a), sum(sum(a)) over (order by b) from t group by b;
select a, sum(a) filter (where a % 2 = 0) over (order by a) from t;
select a, sum(a) over (partition by b) from t order by a;
select a, sum(a) over (order by a rows between 2 following and 4 following) from t;
select a, sum(a) over (order by a rows between 3 preceding and 1 preceding) from t;
select a, count(*) over (order by a desc range between 2 preceding and 1 following) from t;
select a, nth_value(a, 0) over (order by a) from t;
select ntile(0) over () from t;
select a, sum(a) over (order by a rows between -1 preceding and current row) from t;
select row_number() over win from t window win as (partition by b order by a desc);
select * from (select a, rank() over (order by b) r from t) where r > 2;
explain query plan select a, sum(a) over (order by a) from t;
